class _CurrencyListPageState extends State<CurrencyListPage> {
  int _refreshCount = 0;

  @override
  void initState() {
    super.initState();
    widget.refreshTrigger?.addListener(_onRefresh);
  }

  @override
  void didUpdateWidget(CurrencyListPage oldWidget) {
    super.didUpdateWidget(oldWidget);
    oldWidget.refreshTrigger?.removeListener(_onRefresh);
    widget.refreshTrigger?.addListener(_onRefresh);
  }

  @override
  void dispose() {
    widget.refreshTrigger?.removeListener(_onRefresh);
    super.dispose();
  }

  void _onRefresh() {
    setState(() {
      _refreshCount = widget.refreshTrigger!.value;
      // Пересоздаём Future здесь
      final currencyRepository = context.read<CurrencyRepository>();
      _currencyListFuture = _loadCurrencyData(currencyRepository);
    });
  }

  @override
  Widget build(BuildContext context) { ... }
}
```

