/// Триггер для одновременного обновления курса валют и ленты новостей.
class RefreshTrigger {
  final ValueNotifier<int> _counter = ValueNotifier<int>(0);

  /// Увеличивает счётчик, нотифицируя всех слушателей.
  void trigger() {
    _counter.value++;
  }

  /// Текущее значение счётчика (для подписки).
  int get value => _counter.value;

  /// Подписка на изменения.
  ValueListenable<int> listenable() => _counter;

  void dispose() {
    _counter.dispose();
  }
}
