class _NewsListPageState extends State<NewsListPage> with SingleTickerProviderStateMixin {
  static final _tween = Tween<double>(begin: 0.25, end: 1);

  late Future<List<NewsModel>> _newsListFuture;

  late final AnimationController _scaleController;
  late final Animation<double> _scaleAnimation;

  StreamSubscription<int>? _refreshSubscription;

  @override
  void initState() {
    super.initState();
    _initAnimation();
    _initData();
    _listenRefreshTrigger();
  }

  @override
  void dispose() {
    _refreshSubscription?.cancel();
    _scaleController.dispose();
    super.dispose();
  }

  void _listenRefreshTrigger() {
    final RefreshTrigger trigger = context.read<RefreshTrigger>();
    _refreshSubscription = trigger.listenable().addListener(_onRefresh);
  }

  void _onRefresh() {
    setState(() {
      _initData();
    });
  }

  void _initAnimation() {
    _scaleController = AnimationController(
      vsync: this,
      duration: Duration(milliseconds: 200),
    );
    _scaleAnimation = _tween.animate(_scaleController);
  }

  void _initData() {
    final newsRepository = context.read<NewsRepository>();

    _newsListFuture = newsRepository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true)).then((List<NewsModel> value) {

      _scaleController.forward(from: 0); // перезапускаем анимацию

      return value;
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(context.loc.news)),
      body: FutureBuilder<List<NewsModel>>(
        future: _newsListFuture,
        builder: (BuildContext context, AsyncSnapshot<List<NewsModel>> snapshot) {
          final List<NewsModel>? data = snapshot.data;
          if (data == null) return const SizedBox.shrink();

          return ScaleTransition(
            scale: _scaleAnimation,
            child: ListView.builder(
              itemCount: data.length,
              itemBuilder: (BuildContext context, int index) {
                final NewsModel news = data[index];

                return Padding(
                  key: ValueKey(news.link),
                  padding: index == 0 ? EdgeInsets.zero : const EdgeInsets.only(top: 16),
                  child: NewsCard(model: news),
                );
              },
              padding: const EdgeInsets.fromLTRB(22, 16, 22, 40),
            ),
          );
        },
      ),
    );
  }
}
