6: class CurrencyListPage extends StatefulWidget {
7:   const CurrencyListPage({super.key});
8: 
9:   @override
10:   State<CurrencyListPage> createState() => _CurrencyListPageState();
11: }
12: 
13: class _CurrencyListPageState extends State<CurrencyListPage> with SingleTickerProviderStateMixin {
14:   late final ValueNotifier<List<CurrencyModel>> _filteredCurrenciesNotifier;
15: 
16:   late final AnimationController _fadeController;
17: 
18:   late Future<List<CurrencyModel>> _currencyListFuture;
19: 
20:   List<CurrencyModel> _allCurrencies = [];
21: 
22:   StreamSubscription<int>? _refreshSubscription;
23: 
24:   @override
25:   void initState() {
26:     super.initState();
27:     _initAnimation();
28:     _initData();
29:     _listenRefreshTrigger();
30:   }
31: 
32:   @override
33:   void dispose() {
34:     _refreshSubscription?.cancel();
35:     _filteredCurrenciesNotifier.dispose();
36:     _fadeController.dispose();
37:     super.dispose();
38:   }
39: 
40:   void _listenRefreshTrigger() {
41:     final RefreshTrigger trigger = context.read<RefreshTrigger>();
42:     _refreshSubscription = trigger.listenable().addListener(_onRefresh);
43:   }
44: 
45:   void _onRefresh() {
46:     setState(() {
47:       _initData();
48:     });
49:   }
50: 
51:   void _initAnimation() {
52:     _fadeController = AnimationController(
53:       duration: Duration(milliseconds: 400),
54:       vsync: this,
55:     );
56:   }
57: 
58:   void _initData() {
59:     final currencyRepository = context.read<CurrencyRepository>();
60: 
61:     _currencyListFuture = currencyRepository.fetchRates(const CurrencyPageRequest(base: 'USD')).then((CurrencyPage page) {
62:       final List<CurrencyModel> value = page.items;
63:       _allCurrencies = value;
64:       _filteredCurrenciesNotifier.value = value;
65: 
66:       _fadeController.forward(from: 0); // перезапускаем анимацию
67: 
68:       currencyRepository.saveCurrencyList(value);
69: 
70:       return value;
71:     });
72:   }
73: 
74:   void _filterCurrencies(String query) {
75:     final String lowerQuery = query.toLowerCase();
76:     final Iterable<CurrencyModel> result = _allCurrencies.where((CurrencyModel currency) {
77:       return currency.name.toLowerCase().contains(lowerQuery) || currency.symbol.toLowerCase().contains(lowerQuery);
78:     });
79: 
80:     _filteredCurrenciesNotifier.value = result.toList(growable: false);
81:   }
82: 
83:   @override
84:   Widget build(BuildContext context) {
85:     return Scaffold(
86:       appBar: AppBar(title: Text(context.loc.currencyRate)),
87:       body: FutureBuilder(
88:         future: _currencyListFuture,
89:         builder: (BuildContext context, AsyncSnapshot<List<CurrencyModel>> snapshot) {
90:           final List<CurrencyModel>? data = snapshot.data;
91:           if (data == null) return const SizedBox.shrink();
92: 
93:           return FadeTransition(
94:             opacity: _fadeController.view,
95:             child: Column(
96:               children: [
97:                 Padding(
98:                   padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 22),
99:                   child: SearchView(onChanged: _filterCurrencies),
100:                 ),
101:                 Expanded(
102:                   child: ValueListenableBuilder<List<CurrencyModel>>(
103:                     valueListenable: _filteredCurrenciesNotifier,
104:                     builder: (BuildContext context, List<CurrencyModel> data, _) {
105:                       return ListView.builder(
106:                         itemCount: data.length,
107:                         itemBuilder: (BuildContext context, int index) {
108:                           final CurrencyModel currency = data[index];
109: 
110:                           return Padding(
111:                             key: ValueKey(currency.id),
112:                             padding: index == 0 ? const EdgeInsets.only(top: 20) : const EdgeInsets.only(top: 10),
113:                             child: CurrencyCard(model: currency),
114:                           );
115:                         },
116:                         padding: const EdgeInsets.fromLTRB(22, 0, 22, 40),
117:                       );
118:                     },
119:                   ),
120:                 ),
121:               ],
122:             ),
123:           );
124:         },
125:       ),
126:     );
127:   }
128: }

